const cmds = [
  ["graph_nodes_summary", "\"$HORIZON_BIN\" graph -p Algebraic-Jacobian-Challenge-Rebuild list --json | jq '{total:length, by_type:(group_by(.type)|map({type:.[0].type,count:length})), by_generated:(group_by(.generated)|map({generated:.[0].generated,count:length})), lean_public:([.[]|select(.type==\"lean\" and .private!=true)]|length), lean_private:([.[]|select(.type==\"lean\" and .private==true)]|length), tex_by_status:([.[]|select(.type==\"tex\")]|group_by(.lean_status)|map({status:.[0].lean_status,count:length})), lean_by_status:([.[]|select(.type==\"lean\")]|group_by(.lean_status)|map({status:.[0].lean_status,count:length}))}'", "."],
  ["graph_tex_chapters", "\"$HORIZON_BIN\" graph -p Algebraic-Jacobian-Challenge-Rebuild list --json | jq '[.[]|select(.type==\"tex\")]|group_by(.chapter)|map({chapter:.[0].chapter,count:length})|sort_by(.chapter)'", "."],
  ["graph_edge_summary", "\"$HORIZON_BIN\" graph -p Algebraic-Jacobian-Challenge-Rebuild edges --json | jq '{total:length, by_type:(group_by(.type)|map({type:.[0].type,count:length})), formalizes_sources:([.[]|select(.type==\"formalizes\")|.source]|unique|length), formalizes_targets:([.[]|select(.type==\"formalizes\")|.target]|unique|length), uses_sources:([.[]|select(.type==\"uses\")|.source]|unique|length), uses_targets:([.[]|select(.type==\"uses\")|.target]|unique|length)}'", "."],
  ["graph_authored", "\"$HORIZON_BIN\" graph -p Algebraic-Jacobian-Challenge-Rebuild list --json | jq '[.[]|select(.generated!=\"lean\" and .generated!=\"blueprint\")|{id,type,title,generated}]'", "."],
  ["graph_tex_missing_label", "\"$HORIZON_BIN\" graph -p Algebraic-Jacobian-Challenge-Rebuild list --json | jq '[.[]|select(.type==\"tex\" and (.label==null or .label==\"\"))]|length'", "."],
  ["edges_file_counts", "find hgraph/edges -mindepth 1 -maxdepth 1 -type f -name '*.md' | wc -l", "."]
];
const results = await Promise.all(cmds.map(async ([name, cmd, workdir]) => {
  const r = await tools.exec_command({cmd, workdir, yield_time_ms:30000, max_output_tokens:20000});
  return `--- ${name} ---\n${r.output}`;
}));
results.forEach(text);

const p="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild/blueprint/src";
const cmds=[
 ["common","nl -ba macros/common.tex | sed -n '1,280p'"],
 ["print/web macros","nl -ba macros/print.tex | sed -n '1,220p'; nl -ba macros/web.tex | sed -n '1,220p'"],
 ["entries","nl -ba print.tex | sed -n '1,180p'; nl -ba web.tex | sed -n '1,180p'; nl -ba content.tex | sed -n '1,160p'"],
 ["style","nl -ba blueprint.sty | sed -n '1,260p'"],
 ["build/config","rg --files blueprint | rg '(Makefile|build|latexmk|plastex|README|pyproject|package|lakefile)' | sort; nl -ba latexmkrc | sed -n '1,160p'; nl -ba plastex.cfg | sed -n '1,180p' 2>/dev/null || true"],
 ["existing marker placement","rg -n -S '\\\\(source|lean|uses|notready|leanok|mathlibok|sketch|level|group)\\b' chapters | sed -n '1,220p'"]
];
const rs=await Promise.all(cmds.map(([n,c])=>tools.exec_command({cmd:c,workdir:p,yield_time_ms:10000,max_output_tokens:40000})));
for(let i=0;i<rs.length;i++) text(`${cmds[i][0]}\n${rs[i].output}`);

